import{_ as o,o as a,c as t,a4 as s}from"./chunks/framework.YC5CMuPM.js";const p=JSON.parse('{"title":"Learning path","description":"","frontmatter":{},"headers":[],"relativePath":"guide/learning-path.md","filePath":"guide/learning-path.md","lastUpdated":1790862266000}'),i={name:"guide/learning-path.md"};function n(r,e,l,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h1><p><strong>A route through JUCE in six stages, each pairing a concept page with a real example from <code>examples/</code> and a small exercise.</strong> Each stage builds on the one before, so work through them in order.</p><div class="tip custom-block"><p class="custom-block-title">Setup once</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes flexoki flexoki vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">cd </span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">/path/to/JUCE</span></span>\n<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">cmake </span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">.</span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;"> -B</span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;"> cmake-build</span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;"> -DJUCE_BUILD_EXAMPLES=ON</span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;"> -DJUCE_BUILD_EXTRAS=ON</span></span>\n<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">cmake </span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">--build</span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;"> cmake-build</span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;"> --target</span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;"> DemoRunner</span></span></code></pre></div><p>The <strong>DemoRunner</strong> app lets you browse and run the bundled demos, with their source alongside.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> On Linux, install the packages in <a href="https://github.com/juce-framework/JUCE/blob/master/docs/Linux%20Dependencies.md" target="_blank" rel="noreferrer"><code>docs/Linux Dependencies.md</code></a> first.</p></div><h2 id="_1-foundations-juce-core-and-juce-events" tabindex="-1">1. Foundations: <code>juce_core</code> and <code>juce_events</code> <a class="header-anchor" href="#_1-foundations-juce-core-and-juce-events" aria-label="Permalink to &quot;1. Foundations: `juce_core` and `juce_events`&quot;">​</a></h2><ul><li><strong>Read:</strong> <a href="./core-concepts.html#strings">Core concepts → Strings</a>, <a href="./core-concepts.html#ownership">Ownership</a></li><li><strong>Study:</strong> <code>examples/Utilities/XMLandJSONDemo.h</code>, <code>TimersAndEventsDemo.h</code>, <code>MultithreadingDemo.h</code></li><li><strong>Build:</strong> start from <code>examples/CMake/ConsoleApp</code>. Write a tool that lists every <code>.wav</code> file in a folder (<code>File::findChildFiles</code>) and prints the results as JSON.</li></ul><h2 id="_2-components-and-drawing" tabindex="-1">2. Components and drawing <a class="header-anchor" href="#_2-components-and-drawing" aria-label="Permalink to &quot;2. Components and drawing&quot;">​</a></h2><ul><li><strong>Read:</strong> <a href="./core-concepts.html#components">Core concepts → Components</a>, <a href="./architecture.html#how-the-gui-reaches-your-code">Architecture → How the GUI reaches your code</a></li><li><strong>Study:</strong> <code>examples/GUI/HelloWorldDemo.h</code>, <code>GraphicsDemo.h</code>, <code>FlexBoxDemo.h</code>, <code>LookAndFeelDemo.h</code></li><li><strong>Build:</strong> start from <code>examples/CMake/GuiApp</code>. Make a window with three sliders laid out with <code>FlexBox</code>, and a custom-painted rotary knob using your own <code>LookAndFeel_V4</code> subclass.</li></ul><h2 id="_3-state" tabindex="-1">3. State <a class="header-anchor" href="#_3-state" aria-label="Permalink to &quot;3. State&quot;">​</a></h2><ul><li><strong>Read:</strong> <a href="./core-concepts.html#state">Core concepts → State</a>, <a href="./core-concepts.html#listeners">Listeners</a></li><li><strong>Study:</strong> <code>examples/Utilities/ValueTreesDemo.h</code></li><li><strong>Build:</strong> store your slider values from stage 2 in a <code>ValueTree</code> with an <code>UndoManager</code>. Add undo and redo buttons, and save and load the tree as XML.</li></ul><h2 id="_4-real-time-audio" tabindex="-1">4. Real-time audio <a class="header-anchor" href="#_4-real-time-audio" aria-label="Permalink to &quot;4. Real-time audio&quot;">​</a></h2><ul><li><strong>Read:</strong> <a href="./architecture.html#how-audio-reaches-your-code">Architecture → How audio reaches your code</a>, <a href="./core-concepts.html#threads">Core concepts → Threads</a></li><li><strong>Study:</strong> <code>examples/Audio/AudioAppDemo.h</code>, <code>AudioSettingsDemo.h</code>, <code>AudioPlaybackDemo.h</code>, <code>SimpleFFTDemo.h</code></li><li><strong>Build:</strong> use an <code>AudioAppComponent</code> to generate a sine wave whose frequency is set by a slider. Use a <code>std::atomic&lt;float&gt;</code> and <code>SmoothedValue</code>, then add a level meter fed by a <code>Timer</code>. Deliberately allocate in the callback once, and listen for glitches.</li></ul><h2 id="_5-dsp" tabindex="-1">5. DSP <a class="header-anchor" href="#_5-dsp" aria-label="Permalink to &quot;5. DSP&quot;">​</a></h2><ul><li><strong>Read:</strong> <a href="./../reference/modules.html#juce-dsp">Modules → juce_dsp</a></li><li><strong>Study:</strong> <code>examples/DSP/GainDemo.h</code>, <code>IIRFilterDemo.h</code>, <code>OverdriveDemo.h</code>, <code>ConvolutionDemo.h</code></li><li><strong>Build:</strong> make a <code>dsp::ProcessorChain</code> of gain, filter, and waveshaper, and process your sine through it.</li></ul><h2 id="_6-plug-ins" tabindex="-1">6. Plug-ins <a class="header-anchor" href="#_6-plug-ins" aria-label="Permalink to &quot;6. Plug-ins&quot;">​</a></h2><ul><li><strong>Read:</strong> <a href="./plugin-anatomy.html">Anatomy of a plug-in</a></li><li><strong>Study:</strong> <code>examples/Plugins/GainPluginDemo.h</code>, then <code>AudioPluginDemo.h</code>, <code>DSPModulePluginDemo.h</code>, and <code>WebViewPluginDemo.h</code></li><li><strong>Build:</strong> start from <code>examples/CMake/AudioPlugin</code>. Port your stage-5 chain into a plug-in with an APVTS and slider attachments. Build the VST3 and Standalone targets, and test in <code>extras/AudioPluginHost</code>.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li><strong>Hosting:</strong> <code>examples/Plugins/HostPluginDemo.h</code> and the AudioPluginHost source (<code>extras/AudioPluginHost</code>)</li><li><strong>MIDI 2.0:</strong> <code>examples/Audio/UmpDemo.h</code>, <code>CapabilityInquiryDemo.h</code></li><li><strong>OpenGL and animation:</strong> <code>examples/GUI/OpenGLDemo.h</code>, <code>AnimatorsDemo.h</code></li><li><strong>Read the source:</strong> when a class confuses you, open its header. The Doxygen comments are the real documentation, and the <code>jassert</code>s show intended use.</li></ul><h2 id="how-to-grow-this-site-as-you-learn" tabindex="-1">How to grow this site as you learn <a class="header-anchor" href="#how-to-grow-this-site-as-you-learn" aria-label="Permalink to &quot;How to grow this site as you learn&quot;">​</a></h2><p>Each stage is a chance to add to these docs:</p><ul><li>Add every new term you meet to the <a href="./../reference/glossary.html">glossary</a>.</li><li>When a diagram clarifies something, add a Mermaid block to the relevant page.</li><li>Keep a &quot;gotchas&quot; section on each page for the mistakes you actually made.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Build commands from <a href="https://github.com/juce-framework/JUCE/blob/master/README.md#building-examples-using-cmake" target="_blank" rel="noreferrer"><code>README.md</code></a>; demos and CMake starting points are in <a href="https://github.com/juce-framework/JUCE/blob/master/examples" target="_blank" rel="noreferrer"><code>examples/</code></a>. Every example path on this page was checked against the repository at JUCE 9.0.3, so re-check after upgrading. The exercises are this site&#39;s own suggestions. <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',23)])])}const g=o(i,[["render",n]]);export{p as __pageData,g as default};
